import os,time,re
def io():
    o={}
    for dp,_,fn in os.walk("/sys/fs/cgroup"):
        if "io.stat" in fn:
            rb=rn=0
            for l in open(dp+"/io.stat"):
                for x in l.split():
                    if x.startswith("rbytes="): rb+=int(x[7:])
                    elif x.startswith("rios="): rn+=int(x[5:])
            o[dp[15:] or "/"]=(rb,rn)
    return o
def dk():
    b=n=0
    for l in open("/proc/diskstats"):
        p=l.split()
        if re.fullmatch(r"sd[a-z]",p[2]) or re.fullmatch(r"nvme\dn\d",p[2]): n+=int(p[3]); b+=int(p[5])*512
    return b,n
a,da=io(),dk(); time.sleep(40); b,db=io(),dk()
